 async function connectBrowserWallet(){setError('');setSendResult(null);if(!window.ethereum){setError('No compatible browser wallet was detected. Open this page in a wallet browser or install a compatible EVM wallet.');return;}try{const accounts=await window.ethereum.request({method:'eth_requestAccounts'});const id=Number(BigInt(await window.ethereum.request({method:'eth_chainId'})));setConnectedWallet(accounts?.[0]||'');setWalletChainId(id);if(!accounts?.[0])throw Error('The wallet did not return an account.');setToast('Wallet connected. Sending still requires explicit wallet approval.');}catch(e){setError(e.message||'Wallet connection was rejected.');}}
 async function sendFromConnectedWallet(e){e.preventDefault();setError('');setSendResult(null);if(!window.ethereum||!connectedWallet){setError('Connect your wallet first.');return;}const cfg=CHAINS[chain];if(!cfg.chainId){setError('Direct wallet sending is not enabled for this network yet. Use an EVM network supported below.');return;}if(walletChainId!==cfg.chainId){setError('Your wallet is on chain ID '+walletChainId+'. Switch the wallet to '+cfg.name+' (chain ID '+cfg.chainId+') and reconnect before sending.');return;}const to=sendTo.trim();if(!/^0x[a-fA-F0-9]{40}$/.test(to)){setError('Enter a valid 0x destination address.');return;}if(!/^(?:0|[1-9]\\d*)(?:\\.\\d{1,18})?$/.test(sendAmount)||!/[1-9]/.test(sendAmount)){setError('Enter a positive decimal amount with no more than 18 fractional digits.');return;}const decimals=sendAsset==='usdt'?(cfg.usdtDecimals??6):18;const parts=sendAmount.split('.');const frac=(parts[1]||'').padEnd(decimals,'0');if((parts[1]||'').length>decimals){setError('This asset supports at most '+decimals+' decimal places.');return;}let units;try{units=BigInt(parts[0])*10n**BigInt(decimals)+BigInt(frac||'0');}catch{setError('Invalid amount.');return;}if(units<=0n){setError('Amount must be greater than zero.');return;}let tx;if(sendAsset==='usdt'){if(!cfg.usdt){setError('USDT is not configured for this network.');return;}tx={from:connectedWallet,to:cfg.usdt,data:'0xa9059cbb'+to.slice(2).toLowerCase().padStart(64,'0')+units.toString(16).padStart(64,'0'),value:'0x0'};}else{tx={from:connectedWallet,to,value:'0x'+units.toString(16)};}setSendBusy(true);try{const hash=await window.ethereum.request({method:'eth_sendTransaction',params:[tx]});setSendResult({hash,network:cfg.name,url:cfg.explorer+hash,asset:sendAsset==='usdt'?'USDT':cfg.native,amount:sendAmount,to});setToast('Transaction submitted by wallet. Wait for on-chain confirmation.');}catch(e){setError(e.message||'Wallet did not submit the transaction.');}finally{setSendBusy(false);}}
 function gen(e){e?.preventDefault();const n=Number(amount);if(!Number.isFinite(n)||n<=0||n>1e9){setError('Enter a positive amount for the display receipt.');return;}setError('');const id=makeRef();setReference(id);setReceipt({id,amount:n,network:c.name,time:new Date().toLocaleString()});setToast('Internal reference created. No funds were sent.');}
